// SPDX-License-Identifier: GPL-2.0-only
// CASE: [MapProperty(AllowNull = true)] on members no null can reach - a non-nullable source, a nullable
//       destination - beside one that does accept a null and so says nothing.
// WHY:  Round 32, under the owner's 2026-09-27 ruling that no DWARF warning may need a project-wide NoWarn: a null
//       that is deliberate is accepted per member, in mapping terms, with AllowNull - which drops DWARF070 for that
//       member and changes no generated byte. A statement that accepts nothing is not harmless. It is a pre-signed
//       acceptance: the day its source becomes nullable, the null lands with no DWARF070 and nobody having decided
//       it. So a dead one is reported, with the reason it is dead. A Warning, like DWARF095: the mapping is correct
//       and ships; what is wrong is a written directive that does nothing.
// EXPECT: DWARF116
// EXPECT-MESSAGE DWARF116: [MapProperty(AllowNull = true)] on 'Code' accepts a null that cannot reach it: its source is not a nullable reference
// EXPECT-MESSAGE DWARF116: [MapProperty(AllowNull = true)] on 'Note' accepts a null that cannot reach it: its destination accepts null
// EXPECT-MESSAGE DWARF116: left in place, it would silently accept a null introduced here later
// EXPECT-CS:
// NOTE: 'Name' is the statement doing its job - a null reaches it and is accepted, so there is no DWARF070 for it,
//       and the '!' it keeps is why no CS8601 reaches the generated file either.

#nullable enable

using DwarfMapper;

namespace Demo;

public class Src
{
    public string? Name { get; set; }
    public string Code { get; set; } = "";
    public string? Note { get; set; }
}

public class Dst
{
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string? Note { get; set; }
}

[DwarfMapper]
public partial class M
{
    [MapProperty(nameof(Src.Name), nameof(Dst.Name), AllowNull = true)]
    [MapProperty(nameof(Src.Code), nameof(Dst.Code), AllowNull = true)]
    [MapProperty(nameof(Src.Note), nameof(Dst.Note), AllowNull = true)]
    public partial Dst Map(Src s);
}
